#ifndef ZOVUTILS_TEE_BACKEND_H
#define ZOVUTILS_TEE_BACKEND_H
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
static inline int zov_tee_run(int argc,char**argv){int append=0,ignore_int=0,end=0,nf=0,status=0;FILE**outs=(FILE**)malloc((size_t)(argc+1)*sizeof(FILE*));const char**names=(const char**)malloc((size_t)(argc+1)*sizeof(char*));if(!outs||!names){free(outs);free(names);return 1;}for(int i=0;i<argc;i++){const char*a=argv[i];if(!end&&!strcmp(a,"--")){end=1;continue;}if(!end&&(!strcmp(a,"--help")||!strcmp(a,"--version"))){if(!strcmp(a,"--version"))puts("tee (zovutils) 0.10.2");else puts("Usage: tee [OPTION]... [FILE]...\nCopy standard input to each FILE, and also to standard output.\n  -a, --append              append to the given FILEs, do not overwrite\n  -i, --ignore-interrupts   ignore interrupt signals\n      --help                display this help and exit\n      --version             output version information and exit");free(outs);free(names);return 0;}if(!end&&(!strcmp(a,"-a")||!strcmp(a,"--append"))){append=1;continue;}if(!end&&!strcmp(a,"-i")){ignore_int=1;continue;}if(!end&&a[0]=='-'&&strcmp(a,"-")){fprintf(stderr,"tee: unrecognized option '%s'\nTry 'tee --help' for more information.\n",a);free(outs);free(names);return 1;}names[nf++]=a;}if(ignore_int)signal(SIGINT,SIG_IGN);for(int i=0;i<nf;i++){outs[i]=fopen(names[i],append?"ab":"wb");if(!outs[i]){fprintf(stderr,"tee: %s: %s\n",names[i],strerror(errno));outs[i]=NULL;status=1;}}unsigned char buf[16384];size_t n;while((n=fread(buf,1,sizeof(buf),stdin))){if(fwrite(buf,1,n,stdout)!=n)status=1;for(int i=0;i<nf;i++)if(outs[i]&&fwrite(buf,1,n,outs[i])!=n){fprintf(stderr,"tee: %s: write error: %s\n",names[i],strerror(errno));fclose(outs[i]);outs[i]=NULL;status=1;}}if(ferror(stdin))status=1;if(fflush(stdout)!=0)status=1;for(int i=0;i<nf;i++)if(outs[i]){if(fclose(outs[i])!=0){fprintf(stderr,"tee: %s: write error: %s\n",names[i],strerror(errno));status=1;}}free(outs);free(names);return status;}
#endif
